const execution = $json.execution ?? {};
const workflow = $json.workflow ?? {};
const trigger = $json.trigger ?? {};
return [{ json: {
  workflow_name: String(workflow.name ?? 'OlistCare AI'),
  execution_id: String(execution.id ?? ''),
  execution_url: String(execution.url ?? ''),
  node_name: String(execution.lastNodeExecuted ?? trigger.error?.node?.name ?? 'desconocido'),
  error_message: String(execution.error?.message ?? trigger.error?.message ?? $json.message ?? 'Error no especificado').slice(0, 1000),
  ticket_id: String(trigger.error?.context?.ticket_id ?? ''),
  created_at: new Date().toISOString()
} }];
